function L({registerIndicator:v,sourceValues:B,nulls:M}){v({id:"oa-bbb",name:"Bollinger %B",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"multiplier",type:"number",label:"StdDev Multiplier",default:2,min:.001,max:100,step:.1,tooltip:"Band half-width as a multiple of the standard deviation of the source."}],plots:[{key:"bbb",type:"line",title:"Bollinger %B",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:1,title:"Upper Band Level",color:"#787b86",dashed:!0},{price:.8,title:"Overbought",color:"#ef5350",dashed:!0},{price:.5,title:"Midline",color:"#787b86"},{price:.2,title:"Oversold",color:"#26a69a",dashed:!0},{price:0,title:"Lower Band Level",color:"#787b86",dashed:!0}],calc(s,i){const c=Math.max(1,Math.floor(Number(i.period)||20)),N=Math.max(.001,Number(i.multiplier)||2),x=B(s,i.source??"close"),d=s.length,u=new Array(d).fill(NaN),p=new Array(c).fill(NaN);let t=0,b=0,a=0,n=0;for(let l=0;l<d;l++){const e=x[l];if(!Number.isFinite(e))continue;const o=p[t];Number.isFinite(o)?(a-=o,n-=o*o):b+=1,a+=e,n+=e*e,p[t]=e,t=(t+1)%c;const m=Math.max(1,b),r=a/m,k=Math.max(0,n/m-r*r),w=Math.sqrt(k),f=N*w,g=r+f,h=r-f,y=g-h;u[l]=y>0?(e-h)/y:.5}return{bbb:M(u)}}})}export{L as default};
